public BlockPos groundBlock(boolean ignoreAir) {
        Block block = this.blockState.getBlock();
        BlockPos blockpos = this.blockPosition();
        BlockState blockstate = this.level.getBlockState(blockpos);
        boolean isConcrete = this.blockState.getBlock() instanceof ConcretePowderBlock;
        boolean isConcreteInWater = isConcrete && this.level.getFluidState(blockpos).is(FluidTags.WATER);
        this.setDeltaMovement(this.getDeltaMovement().multiply(0.7D, -0.5D, 0.7D));
        if (blockstate.is(Blocks.MOVING_PISTON))
            return null;
        if (this.cancelDrop) {
            this.discard();
            this.callOnBrokenAfterFall(block, blockpos);
            return null;
        }
        boolean canBeReplaced = blockstate.canBeReplaced(new DirectionalPlaceContext(this.level, blockpos, Direction.DOWN, ItemStack.EMPTY, Direction.UP));
        boolean isFreeBelow = FallingBlock.isFree(this.level.getBlockState(blockpos.below())) && (!isConcrete || !isConcreteInWater);
        boolean canSurvive = this.blockState.canSurvive(this.level, blockpos) && (!isFreeBelow || ignoreAir);
        if (canBeReplaced && canSurvive) {
            if (this.blockState.hasProperty(BlockStateProperties.WATERLOGGED) && this.level.getFluidState(blockpos).getType() == Fluids.WATER) {
                this.blockState = this.blockState.setValue(BlockStateProperties.WATERLOGGED, Boolean.TRUE);
            }

            if (this.level.setBlock(blockpos, this.blockState, 3)) {
                ((ServerLevel) this.level).getChunkSource().chunkMap.broadcast(this, new ClientboundBlockUpdatePacket(blockpos, this.level.getBlockState(blockpos)));
                this.discard();
                if (block instanceof Fallable fallable) {
                    fallable.onLand(this.level, blockpos, this.blockState, blockstate, new FallingBlockEntity(level, this.getX(), this.getY(), this.getZ(), this.blockState));
                } else if (context != null && resolver != null) {
                    RewindAttachment.get(context).addRewindEvent(level.getGameTime(), new EntityToBlockRewind(this, blockpos, this.blockState));
                    ShapersFocus.tryPropagateBlockSpell(new BlockHitResult(
                            new Vec3(blockpos.getX(), blockpos.getY(), blockpos.getZ()), Direction.DOWN, blockpos, false
                    ), level, getOwner(), context, resolver);
                }

                if (this.blockData != null && this.blockState.hasBlockEntity()) {
                    BlockEntity blockentity = this.level.getBlockEntity(blockpos);
                    if (blockentity != null) {

                        try {
                            blockentity.loadWithComponents(this.blockData, level.registryAccess());
                            if (blockentity instanceof SkullBlockEntity sk && this.blockData != null && this.blockData.contains("SkullOwner")) {
                                sk.setOwner(ANCodecs.decode(level.registryAccess(), ResolvableProfile.CODEC, this.blockData.getCompound("SkullOwner")));
                            }
                        } catch (Exception exception) {
                            exception.printStackTrace();
                        }

                        blockentity.setChanged();
                    }
                }
                if (this.level.getBlockEntity(blockpos) instanceof MageBlockTile mbt) {
                    if (context != null) {
                        mbt.color = context.getSpell().particleTimeline().get(ParticleTimelineRegistry.MAGEBLOCK_TIMELINE.get()).getColor();
                    }
                    mbt.setChanged();
                }

                return blockpos;
            } else if (this.dropItem && this.level.getGameRules().getBoolean(GameRules.RULE_DOENTITYDROPS)) {
                this.discard();
                this.callOnBrokenAfterFall(block, blockpos);
                ItemStack itemstack = new ItemStack(block);
                if (this.blockData != null && this.getBlockState().is(Blocks.PLAYER_HEAD)) {
                    ResolvableProfile.CODEC
                            .parse(NbtOps.INSTANCE, blockData.get("profile"))
                            .resultOrPartial().ifPresent(profile -> itemstack.set(DataComponents.PROFILE, profile));
                }
                this.spawnAtLocation(itemstack);
                return null;
            }
        } else {
            this.discard();
            if (this.dropItem && this.level.getGameRules().getBoolean(GameRules.RULE_DOENTITYDROPS)) {
                this.callOnBrokenAfterFall(block, blockpos);
                ItemStack itemstack = new ItemStack(block);
                if (this.blockData != null && this.getBlockState().is(Blocks.PLAYER_HEAD)) {
                    ResolvableProfile.CODEC
                            .parse(NbtOps.INSTANCE, blockData.get("profile"))
                            .resultOrPartial().ifPresent(profile -> itemstack.set(DataComponents.PROFILE, profile));

                }
                this.spawnAtLocation(itemstack);
            }
        }
        return null;
    }

public static boolean canFall(Level level, BlockPos pos, Entity owner, SpellStats spellStats) {
        if (level.isEmptyBlock(pos)
                || !level.getFluidState(pos).isEmpty()
                || level.getBlockState(pos).is(BlockTagProvider.RELOCATION_NOT_SUPPORTED)
                || (level.getBlockEntity(pos) != null && !(level.getBlockEntity(pos) instanceof MageBlockTile
                || level.getBlockEntity(pos) instanceof SkullBlockEntity))) {
            return false;
        }
        return BlockUtil.canBlockBeHarvested(spellStats, level, pos) && BlockUtil.destroyRespectsClaim((LivingEntity) owner, level, pos);
    }

public static @Nullable EnchantedFallingBlock fall(Level level, BlockPos pos, Entity owner, SpellContext context, SpellResolver resolver, SpellStats spellStats) {
        if (!canFall(level, pos, owner, spellStats)) return null;
        BlockState blockState = level.getBlockState(pos);
        EnchantedFallingBlock fallingblockentity;
        if (level.getBlockEntity(pos) instanceof MageBlockTile tile) {
            fallingblockentity = new EnchantedMageblock(level, pos.getX() + 0.5D, pos.getY(), pos.getZ() + 0.5D, blockState.hasProperty(BlockStateProperties.WATERLOGGED) ? blockState.setValue(BlockStateProperties.WATERLOGGED, Boolean.FALSE) : blockState);
            fallingblockentity.resolver = resolver;
        } else if (level.getBlockEntity(pos) instanceof SkullBlockEntity tile) {
            fallingblockentity = new EnchantedSkull(level, pos.getX() + 0.5D, pos.getY(), pos.getZ() + 0.5D, blockState.hasProperty(BlockStateProperties.WATERLOGGED) ? blockState.setValue(BlockStateProperties.WATERLOGGED, Boolean.FALSE) : blockState);
        } else {
            fallingblockentity = new EnchantedFallingBlock(level, pos.getX() + 0.5D, pos.getY(), pos.getZ() + 0.5D, blockState.hasProperty(BlockStateProperties.WATERLOGGED) ? blockState.setValue(BlockStateProperties.WATERLOGGED, Boolean.FALSE) : blockState, resolver);
        }
        if (level.getBlockEntity(pos) != null) {
            fallingblockentity.blockData = level.getBlockEntity(pos).saveWithoutMetadata(level.registryAccess());
        }
        level.addFreshEntity(fallingblockentity);
        fallingblockentity.setOwner(owner);
        fallingblockentity.context = context;
        fallingblockentity.baseDamage = (float) (9.0f + spellStats.getDamageModifier());
        fallingblockentity.dropItem = !blockState.is(BlockTagProvider.GRAVITY_BLACKLIST);
        fallingblockentity.spellStats = spellStats;
        if (resolver.hasFocus(ItemsRegistry.SHAPERS_FOCUS.get())) {
            fallingblockentity.hurtEntities = true;
        }
        if (context != null) {
            RewindAttachment rewindAttachment = RewindAttachment.get(context);
            rewindAttachment.addRewindEvent(level.getGameTime(), new BlockToEntityRewind(pos, blockState));
        }
        level.setBlock(pos, blockState.getFluidState().createLegacyBlock(), 3);
        return fallingblockentity;
    }

@Override
    public void tick() {
        super.tick();
        if (this.blockState.isAir()) {
            this.discard();
            return;
        }
        Block block = this.blockState.getBlock();
        ++this.time;
        if (!this.isNoGravity()) {
            this.setDeltaMovement(this.getDeltaMovement().add(0.0D, -0.04D, 0.0D));
        }
        EntityHitResult hitEntity = findHitEntity(this.position, this.position.add(this.getDeltaMovement()));
        if (hitEntity != null) {
            onHitEntity(hitEntity);
        }
        this.move(MoverType.SELF, this.getDeltaMovement());
        if (!this.level.isClientSide && !this.isRemoved()) {
            BlockPos blockpos = this.blockPosition();
            boolean isConcrete = this.blockState.getBlock() instanceof ConcretePowderBlock;
            boolean isConcreteInWater = isConcrete && this.level.getFluidState(blockpos).is(FluidTags.WATER);
            double d0 = this.getDeltaMovement().lengthSqr();
            if (isConcrete && d0 > 1.0D) { // if we are concrete powder
                BlockHitResult blockhitresult = this.level.clip(new ClipContext(new Vec3(this.xo, this.yo, this.zo), this.position(), ClipContext.Block.COLLIDER, ClipContext.Fluid.SOURCE_ONLY, this));
                if (blockhitresult.getType() != HitResult.Type.MISS && this.level.getFluidState(blockhitresult.getBlockPos()).is(FluidTags.WATER)) {
                    blockpos = blockhitresult.getBlockPos();
                    isConcreteInWater = true;
                }
            }

            if (!this.onGround() && !isConcreteInWater) {
                if (!this.level.isClientSide && (this.time > 100 && (blockpos.getY() <= this.level.getMinBuildHeight() || blockpos.getY() > this.level.getMaxBuildHeight()) || this.time > 600)) {
                    if (this.dropItem && this.level.getGameRules().getBoolean(GameRules.RULE_DOENTITYDROPS)) {
                        this.spawnAtLocation(block);
                    }

                    this.discard();
                }
            } else { // on ground
                if (this instanceof IRewindable rewindable && !rewindable.isRewinding()) {
                    this.groundBlock(false);
                }
            }
        }
        this.setDeltaMovement(this.getDeltaMovement().scale(0.98D));
    }

@Override
    protected void onHitEntity(@NotNull EntityHitResult pResult) {
        if (!hurtEntities)
            return;
        super.onHitEntity(pResult);
        Entity entity = pResult.getEntity();
        float f = (float) this.getDeltaMovement().length();
        int i = Mth.ceil(Mth.clamp((Math.min(f, 2.5) * this.baseDamage) + getStateDamageBonus(), 0.0D, 2.147483647E9D));
        this.piercingIgnoreEntityIds.add(entity.getId());

        Entity owner = this.getOwner();
        DamageSource damagesource;
        damagesource = getDamageSource(owner, entity);

        boolean isEnderman = entity.getType() == EntityType.ENDERMAN;
        int k = entity.getRemainingFireTicks();
        if (this.isOnFire() && !isEnderman) {
            entity.igniteForTicks(5);
        }

        if (entity.hurt(damagesource, (float) i)) {
            if (isEnderman) {
                return;
            }

            if (entity instanceof LivingEntity livingentity) {

                if (this.knockback > 0) {
                    Vec3 vec3 = this.getDeltaMovement().multiply(1.0D, 0.0D, 1.0D).normalize().scale((double) this.knockback * 0.6D);
                    if (vec3.lengthSqr() > 0.0D) {
                        livingentity.push(vec3.x, 0.1D, vec3.z);
                    }
                }

                this.doPostHurtEffects(livingentity);
            }

            this.playSound(this.blockState.getSoundType().getBreakSound(), 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));

        } else {
            entity.setRemainingFireTicks(k);
        }
    }

public @NotNull DamageSource getDamageSource(Entity owner, Entity entity) {
        DamageSource damagesource;
        if (owner == null) {
            damagesource = level.damageSources().thrown(this, owner);
        } else {
            damagesource = level.damageSources().thrown(this, owner);
            if (owner instanceof LivingEntity livingOwner) {
                livingOwner.setLastHurtMob(entity);
            }
        }
        return damagesource;
    }

@Override
    public void tick() {
        super.tick();
        if (level.isClientSide && !initMusic) {
            initMusic = true;
            ((Runnable) () -> ChimeraMusic.play(WildenChimera.this)).run();
        }

        // written like this allows for hotswap
        // this.goalSelector.getAvailableGoals().stream().filter(WrappedGoal::isRunning).map(WrappedGoal::getGoal).forEach(System.out::println);


        if (!level.isClientSide && isDefensive()) {
            this.getNavigation().stop();
        }
        if (level.isClientSide && isFlying() && random.nextInt(18) == 0) {

            this.level.playLocalSound(this.getX(), this.getY(), this.getZ(), SoundEvents.BAT_LOOP, this.getSoundSource(),
                    0.95F + this.random.nextFloat() * 0.05F,
                    0.3f + this.random.nextFloat() * 0.05F,
                    false);

        }

        if (!level.isClientSide && this.isInLava() && this.level.getGameTime() % 10 == 0) {
            this.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SPEED, 20, 4));
            this.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE, 20, 3));
            this.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 20));
            this.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 20, 3));

        }

        if (this.isFlying()) {
            this.navigation.stop();
            flyingNavigator.tick();
        }

        if (!level.isClientSide) {
            // Reduce skill cooldown
            if (diveCooldown > 0) {
                diveCooldown--;
                if (this.isInLava() || this.isInWater())
                    diveCooldown -= 2;
            }
            if (summonCooldown > 0) summonCooldown--;
            if (spikeCooldown > 0) spikeCooldown--;
            if (ramCooldown > 0) ramCooldown--;

            if (getTarget() != null && this.invulnerableTime == 0 && !this.isDefensive() && !this.isFlying() && (this.onGround() || isInWater())) {
                var path = getNavigation().createPath(getTarget(), 1);
                if (path == null || !path.canReach() || getTarget().getY() - (this.getY() + 2) >= 3) {
                    rageTimer--;
                }
            }

        }

        if (!level.isClientSide && getPhaseSwapping() && !this.dead) {
            if (swapTicks < 60) {
                swapTicks++;
                this.navigation.stop();
            } else {
                this.removeAllEffects();
                this.setPhaseSwapping(false);
                for (LivingEntity e : level.getEntitiesOfClass(Player.class, new AABB(this.blockPosition()).inflate(5))) {
                    EntitySpellResolver resolver = new EntitySpellResolver(new SpellContext(level, new Spell().add(MethodTouch.INSTANCE)
                            .add(EffectLaunch.INSTANCE)
                            .add(AugmentAmplify.INSTANCE, 2)
                            .add(EffectDelay.INSTANCE)
                            .add(EffectKnockback.INSTANCE)
                            .add(AugmentAmplify.INSTANCE, 2)
                            , this, new LivingCaster(this)));
                    resolver.onCastOnEntity(ItemStack.EMPTY, e, InteractionHand.MAIN_HAND);
                }
                getRandomUpgrade();
                ParticleUtil.spawnPoof((ServerLevel) level, blockPosition().above());
                if (getPhase() == 1)
                    rageTimer = 200;
                swapTicks = 0;
            }
        }

        if (getPhaseSwapping() && level.isClientSide) {
            spawnPhaseParticles(blockPosition(), level, getPhase());
        }
    }

@Override
    public boolean hurt(DamageSource source, float amount) {
        if (source.is(DamageTypes.CACTUS) || source.is(DamageTypes.SWEET_BERRY_BUSH) || source.is(DamageTypes.IN_WALL) || source.is(DamageTypes.LAVA) || source.is(DamageTypes.DROWN))
            return false;
        if (source.is(DamageTypes.FREEZE))
            amount = amount / 2;
        if (this.getPhaseSwapping())
            return false;

        Entity entity = source.getEntity();
        if (entity instanceof LivingEntity entity1 && !entity.equals(this)) {
            if (isDefensive() && !source.is(DamageTypes.THORNS)) {
                if (!source.is(DamageTypeTags.BYPASSES_ARMOR) && BlockUtil.distanceFrom(level, entity.position, position) <= 3) {
                    entity.hurt(level.damageSources().thorns(this), 6.0f);
                }
            }

            // Omit our summoned sources that might aggro or accidentally hurt us
            if (entity1 instanceof WildenStalker || entity1 instanceof WildenGuardian || entity instanceof WildenHunter
                    || entity instanceof ISummon && ((ISummon) entity).getOwnerUUID() != null && ((ISummon) entity).getOwnerUUID().equals(this.getUUID())
                    || entity1 instanceof SummonWolf && ((SummonWolf) entity1).isWildenSummon)
                return false;
        }

        if (isDefensive())
            return false;
        var threshold = this.getMaxHealth() / 4;
        var nextMin = this.getMaxHealth() - threshold * (1 + getPhase());
        boolean res = super.hurt(source, amount);
        if (!this.level.isClientSide && this.getHealth() <= nextMin && getPhase() < 3) {
            this.setPhaseSwapping(true);
            this.setPhase(this.getPhase() + 1);
            this.getNavigation().stop();
            this.setHealth(nextMin);
            this.dead = false;
            this.setFlying(false);
            this.setDefensiveMode(false);
            isRamGoal = false;
        }
        return res;
    }

public void getRandomUpgrade() {
        ArrayList<Integer> upgrades = new ArrayList<>();
        if (!this.hasWings())
            upgrades.add(0);
        if (!this.hasSpikes())
            upgrades.add(1);
        if (!this.hasHorns())
            upgrades.add(2);
        if (upgrades.isEmpty())
            return;
        int upgrade = upgrades.get(random.nextInt(upgrades.size()));
        switch (upgrade) {
            case 0 -> setWings(true);
            case 1 -> setSpikes(true);
            case 2 -> setHorns(true);
        }
    }

@Override
    public void load(@NotNull CompoundTag tag) {
        super.load(tag);
        setHorns(tag.getBoolean("horns"));
        setSpikes(tag.getBoolean("spikes"));
        setWings(tag.getBoolean("wings"));
        setPhase(tag.getInt("phase"));
        setDefensiveMode(tag.getBoolean("defensive"));
        setPhaseSwapping(tag.getBoolean("swapping"));
        summonCooldown = tag.getInt("summonCooldown");
        diveCooldown = tag.getInt("diveCooldown");
        spikeCooldown = tag.getInt("spikeCooldown");
        ramCooldown = tag.getInt("ramCooldown");
        rageTimer = tag.getInt("rage");
        swapTicks = tag.getInt("swapTicks");
    }

@Override
    public boolean save(CompoundTag tag) {
        tag.putBoolean("spikes", hasSpikes());
        tag.putBoolean("horns", hasHorns());
        tag.putBoolean("wings", hasWings());
        tag.putInt("phase", getPhase());
        tag.putBoolean("defensive", isDefensive());
        tag.putInt("summonCooldown", summonCooldown);
        tag.putInt("diveCooldown", diveCooldown);
        tag.putInt("spikeCooldown", spikeCooldown);
        tag.putInt("ramCooldown", ramCooldown);
        tag.putBoolean("swapping", getPhaseSwapping());
        tag.putInt("rage", rageTimer);
        tag.putInt("swapTicks", swapTicks);
        return super.save(tag);
    }

