public void attackMobs(ItemStack pStack, LivingEntity pTarget, Player pPlayer){
        int enchantment = pStack.getEnchantmentLevel(ModEnchantments.SOUL_EATER.get());
        int soulEater = Mth.clamp(enchantment + 1, 1, 10);
        if (SEHelper.getSoulGiven(pTarget) > 0) {
            SEHelper.increaseSouls(pPlayer, ItemConfig.DarkScytheSouls.get() * soulEater);
        }

        float f = (float)pPlayer.getAttributeValue(Attributes.ATTACK_DAMAGE);
        float f1 = EnchantmentHelper.getDamageBonus(pPlayer.getMainHandItem(), pTarget.getMobType());
        float f2 = pPlayer.getAttackStrengthScale(0.5F);
        f = f * (0.2F + f2 * f2 * 0.8F);
        f1 = f1 * f2;
        f = f + f1;

        if (f > 0.5F || f1 > 0.5F) {
            float f3 = 1.0F + EnchantmentHelper.getSweepingDamageRatio(pPlayer) * f;
            int j = EnchantmentHelper.getFireAspect(pPlayer);
            double area = 1.0D;
            if (f2 > 0.9F) {
                area = 2.0D;
            }
            for (LivingEntity livingentity : pPlayer.level.getEntitiesOfClass(LivingEntity.class, pTarget.getBoundingBox().inflate(area, 0.25D, area))) {
                if (livingentity != pPlayer && livingentity != pTarget && !pPlayer.isAlliedTo(livingentity) && (!(livingentity instanceof ArmorStand) || !((ArmorStand) livingentity).isMarker()) && pPlayer.distanceToSqr(livingentity) < 16.0D && livingentity != pPlayer.getVehicle()) {
                    livingentity.knockback(0.4F, (double) Mth.sin(pPlayer.getYRot() * ((float) Math.PI / 180F)), (double) (-Mth.cos(pPlayer.getYRot() * ((float) Math.PI / 180F))));
                    if (livingentity.hurt(livingentity.damageSources().playerAttack(pPlayer), f3)) {
                        if (j > 0) {
                            livingentity.setSecondsOnFire(j * 4);
                        }
                        pStack.hurtAndBreak(1, pPlayer, (p_220045_0_) ->
                                p_220045_0_.broadcastBreakEvent(EquipmentSlot.MAINHAND));
                        boolean giveSoul = false;
                        if (livingentity instanceof OwnableEntity owned){
                            if (owned.getOwner() != pPlayer){
                                giveSoul = true;
                            }
                        } else {
                            giveSoul = true;
                        }
                        if (giveSoul) {
                            if (SEHelper.getSoulGiven(livingentity) > 0) {
                                SEHelper.increaseSouls(pPlayer, ItemConfig.DarkScytheSouls.get() * soulEater);
                            }
                        }
                        EnchantmentHelper.doPostHurtEffects(livingentity, pPlayer);
                        EnchantmentHelper.doPostDamageEffects(pPlayer, livingentity);
                    }
                }
            }
        }

        pPlayer.level.playSound((Player) null, pPlayer.getX(), pPlayer.getY(), pPlayer.getZ(), ModSounds.SCYTHE_SWING.get(), pPlayer.getSoundSource(), 1.0F, 1.0F);
        pPlayer.sweepAttack();
    }

public boolean hurtEnemy(ItemStack pStack, LivingEntity pTarget, LivingEntity pAttacker) {
        pStack.hurtAndBreak(1, pAttacker, (p_220045_0_) ->
                p_220045_0_.broadcastBreakEvent(EquipmentSlot.MAINHAND));
        if (pAttacker instanceof Player player){
            this.attackMobs(pStack, pTarget, player);
        }
        return true;
    }

public void attackMobs(LivingEntity pTarget, AbstractReaper reaper){
            if (reaper.getMasterOwner() instanceof Player player) {
                if (SEHelper.getSoulGiven(pTarget) > 0) {
                    SEHelper.increaseSouls(player, ItemConfig.DarkScytheSouls.get() * 5);
                }
            }
            float f = (float)reaper.getAttributeValue(Attributes.ATTACK_DAMAGE);
            float f1 = EnchantmentHelper.getDamageBonus(reaper.getMainHandItem(), pTarget.getMobType());
            float f2 = 1.0F;
            f = f * (0.2F + f2 * f2 * 0.8F);
            f1 = f1 * f2;
            f = f + f1;

            float f3 = 1.0F + SweepingEdgeEnchantment.getSweepingDamageRatio(3) * f;
            int j = EnchantmentHelper.getFireAspect(reaper);
            double area = 2.0D;
            for (LivingEntity livingentity : reaper.level.getEntitiesOfClass(LivingEntity.class, this.reaper.getBoundingBox().move(this.getHorizontalLookAngle().scale(2.0D)).inflate(area, area, area))) {
                if (livingentity != reaper && !MobUtil.areAllies(reaper, livingentity) && (!(livingentity instanceof ArmorStand) || !((ArmorStand) livingentity).isMarker()) && reaper.distanceToSqr(livingentity) < 16.0D && livingentity != reaper.getVehicle()) {
                    livingentity.knockback(0.4F, (double) Mth.sin(reaper.getYRot() * ((float) Math.PI / 180F)), (double) (-Mth.cos(reaper.getYRot() * ((float) Math.PI / 180F))));
                    if (livingentity.hurt(this.reaper.getServantAttack(), f3)) {
                        if (j > 0) {
                            livingentity.setSecondsOnFire(j * 4);
                        }
                        if (reaper.getMasterOwner() instanceof Player player) {
                            boolean giveSoul = false;
                            if (livingentity instanceof IOwned owned) {
                                if (owned.getMasterOwner() != reaper) {
                                    giveSoul = true;
                                }
                            } else {
                                giveSoul = true;
                            }
                            if (giveSoul) {
                                if (SEHelper.getSoulGiven(livingentity) > 0) {
                                    SEHelper.increaseSouls(player, ItemConfig.DarkScytheSouls.get() * 5);
                                }
                            }
                        }
                        EnchantmentHelper.doPostHurtEffects(livingentity, reaper);
                        EnchantmentHelper.doPostDamageEffects(reaper, livingentity);
                    }
                }
            }

            reaper.level.playSound(null, reaper.getX(), reaper.getY(), reaper.getZ(), ModSounds.SCYTHE_SWING.get(), reaper.getSoundSource(), 1.0F, 1.0F);
            double d0 = -Mth.sin(reaper.getYRot() * ((float)Math.PI / 180F));
            double d1 = Mth.cos(reaper.getYRot() * ((float)Math.PI / 180F));
            if (reaper.level instanceof ServerLevel serverLevel) {
                serverLevel.sendParticles(ParticleTypes.SWEEP_ATTACK, reaper.getX() + d0, reaper.getY(0.5D), reaper.getZ() + d1, 0, d0, 0.0D, d1, 0.0D);
            }
        }

@Override
	protected void onImpact(RayTraceResult rayTrace){

		if(!this.world.isRemote){

			Entity entityHit = rayTrace.entityHit;

			if(entityHit != null){
				// This is if the spark bomb gets a direct hit
				float damage = Spells.spark_bomb.getProperty(Spell.DIRECT_DAMAGE).floatValue() * damageMultiplier;

				this.playSound(WizardrySounds.ENTITY_SPARK_BOMB_HIT, 1.0F, 1.2F / (this.rand.nextFloat() * 0.2F + 0.9F));

				entityHit.attackEntityFrom(
						MagicDamage.causeIndirectMagicDamage(this, this.getThrower(), DamageType.SHOCK).setProjectile(),
						damage);
			}

			double seekerRange = Spells.spark_bomb.getProperty(Spell.EFFECT_RADIUS).doubleValue() * blastMultiplier;

			List<EntityLivingBase> targets = EntityUtils.getLivingWithinRadius(seekerRange, this.posX, this.posY,
					this.posZ, this.world);

			List<Integer> secondaryTargetIDs = new ArrayList<>();

			for(int i = 0; i < Math.min(targets.size(), Spells.spark_bomb.getProperty(SECONDARY_MAX_TARGETS).intValue()); i++){

				boolean flag = targets.get(i) != entityHit && targets.get(i) != this.getThrower()
						&& !(targets.get(i) instanceof EntityPlayer
								&& ((EntityPlayer)targets.get(i)).isCreative());

				if(flag){
					EntityLivingBase target = targets.get(i);

					target.playSound(WizardrySounds.ENTITY_SPARK_BOMB_CHAIN, 1.0F, rand.nextFloat() * 0.4F + 1.5F);

					target.attackEntityFrom(
							MagicDamage.causeIndirectMagicDamage(this, this.getThrower(), DamageType.SHOCK),
							Spells.spark_bomb.getProperty(Spell.SPLASH_DAMAGE).floatValue() * damageMultiplier);

					secondaryTargetIDs.add(target.getEntityId());
				}
			}

			// Notify clients to play the explosion effect, including lightning arcs to secondary targets
			int[] idArray = secondaryTargetIDs.stream().mapToInt(Integer::intValue).toArray();
			WizardryPacketHandler.net.sendToAllAround(
					new PacketBombExplosion.Message(PacketBombExplosion.SPARK_BOMB, posX, posY + height / 2, posZ,
							blastMultiplier, idArray),
					new NetworkRegistry.TargetPoint(world.provider.getDimension(), posX, posY, posZ, 64));

			this.playSound(WizardrySounds.ENTITY_SPARK_BOMB_HIT_BLOCK, 0.5f, 0.5f);
		}

		this.setDead();
	}

@Override
	public IMessage onMessage(Message message, MessageContext ctx){
		if(ctx.side.isClient()){
			net.minecraft.client.Minecraft.getMinecraft().addScheduledTask(
					() -> Wizardry.proxy.handleBombExplosionPacket(message));
		}
		return null;
	}

@Override
	public void handleBombExplosionPacket(PacketBombExplosion.Message message){

		net.minecraft.world.World world = Minecraft.getMinecraft().world;
		double x = message.x, y = message.y, z = message.z;
		float blastMultiplier = message.blastMultiplier;

		switch(message.bombType){

			case PacketBombExplosion.FIREBOMB:
				ParticleBuilder.create(Type.FLASH).pos(x, y, z).scale(5 * blastMultiplier).clr(1, 0.6f, 0).spawn(world);
				for(int i = 0; i < 60 * blastMultiplier; i++){
					ParticleBuilder.create(Type.MAGIC_FIRE, world.rand, x, y, z, 2 * blastMultiplier, false)
							.time(10 + world.rand.nextInt(4)).scale(2 + world.rand.nextFloat()).spawn(world);
					ParticleBuilder.create(Type.DARK_MAGIC, world.rand, x, y, z, 2 * blastMultiplier, false)
							.clr(1.0f, 0.2f + world.rand.nextFloat() * 0.4f, 0.0f).spawn(world);
				}
				world.spawnParticle(EnumParticleTypes.EXPLOSION_LARGE, x, y, z, 0, 0, 0);
				break;

			case PacketBombExplosion.POISON_BOMB:
				ParticleBuilder.create(Type.FLASH).pos(x, y, z).scale(5 * blastMultiplier)
						.clr(0.2f + world.rand.nextFloat() * 0.3f, 0.6f, 0.0f).spawn(world);
				for(int i = 0; i < 60 * blastMultiplier; i++){
					ParticleBuilder.create(Type.SPARKLE, world.rand, x, y, z, 2 * blastMultiplier, false).time(35)
							.scale(2).clr(0.2f + world.rand.nextFloat() * 0.3f, 0.6f, 0.0f).spawn(world);
					ParticleBuilder.create(Type.DARK_MAGIC, world.rand, x, y, z, 2 * blastMultiplier, false)
							.clr(0.2f + world.rand.nextFloat() * 0.2f, 0.8f, 0.0f).spawn(world);
				}
				world.spawnParticle(EnumParticleTypes.EXPLOSION_LARGE, x, y, z, 0, 0, 0);
				break;

			case PacketBombExplosion.SMOKE_BOMB:
				ParticleBuilder.create(Type.FLASH).pos(x, y, z).scale(5 * blastMultiplier).clr(0, 0, 0).spawn(world);
				world.spawnParticle(EnumParticleTypes.EXPLOSION_LARGE, x, y, z, 0, 0, 0);
				for(int i = 0; i < 60 * blastMultiplier; i++){
					float brightness = world.rand.nextFloat() * 0.1f + 0.1f;
					ParticleBuilder.create(Type.CLOUD, world.rand, x, y, z, 2 * blastMultiplier, false)
							.clr(brightness, brightness, brightness).time(80 + world.rand.nextInt(12)).shaded(true).spawn(world);
					brightness = world.rand.nextFloat() * 0.3f;
					ParticleBuilder.create(Type.DARK_MAGIC, world.rand, x, y, z, 2 * blastMultiplier, false)
							.clr(brightness, brightness, brightness).spawn(world);
				}
				break;

			case PacketBombExplosion.SPARK_BOMB:
				ParticleBuilder.spawnShockParticles(world, x, y, z);
				for(int id : message.secondaryTargetIDs){
					net.minecraft.entity.Entity target = world.getEntityByID(id);
					if(target instanceof net.minecraft.entity.EntityLivingBase){
						ParticleBuilder.create(Type.LIGHTNING).pos(x, y, z).target(target).spawn(world);
						ParticleBuilder.spawnShockParticles(world, target.posX,
								target.posY + target.height / 2, target.posZ);
					}
				}
				break;
		}
	}

@Override
    public boolean attackEntityFrom(DamageSource damageSource, float amount) {
        boolean canHarmInCreative = damageSource.canHarmInCreative();
        Entity attacker = damageSource.getTrueSource();

        if (!this.isCarcass()) {
            if (this.getHealth() - amount <= 0.0F) {
                if (!canHarmInCreative) {
                    this.playSound(this.getSoundForAnimation(EntityAnimation.DYING.get()), this.getSoundVolume(), this.getSoundPitch());
                    this.setHealth(this.getMaxHealth());
                    this.setCarcass(true);
                    return true;
                }

                if (attacker instanceof DinosaurEntity) {
                    this.getRelationship(attacker, true).onAttacked(amount);
                }

                return super.attackEntityFrom(damageSource, amount);
            } else {
                if (this.getAnimation() == EntityAnimation.RESTING.get() && !this.world.isRemote) {
                    this.setAnimation(EntityAnimation.IDLE.get());
                    this.isSittingNaturally = false;
                }

                if (!this.world.isRemote) {
                    if (!((float)this.hurtResistantTime > (float)this.maxHurtResistantTime / 2.0F))
                        this.setAnimation(EntityAnimation.INJURED.get());
                }

                if (this.shouldSleep()) {
                    this.disturbSleep();
                }

                if(attacker instanceof EntityLivingBase) {
                    this.respondToAttack((EntityLivingBase)attacker);
                }

                return super.attackEntityFrom(damageSource, amount);
            }
        } else if (!this.world.isRemote) {

            if(!(((float)this.hurtResistantTime > (float)this.maxHurtResistantTime / 2.0F))) {
                boolean carcassAllowed = RebornConfig.ENTITIES.allowCarcass;
                if(!carcassAllowed) {
                    this.dropMeat(attacker);
                    this.onDeath(damageSource);
                    this.setDead();
                }

                if (damageSource != DamageSource.DROWN) {
                    if (!this.dead && this.carcassHealth >= 0 && this.world.getGameRules().getBoolean("doMobLoot")) {
                        this.dropMeat(attacker);
                    }

                    if (this.carcassHealth <= 0) {
                        this.onDeath(damageSource);
                        this.setDead();
                    }

                    this.carcassHealth--;
                }

                if (canHarmInCreative) {
                    return super.attackEntityFrom(damageSource, amount);
                }

                if (this.hurtResistantTime <= this.maxHurtResistantTime / 2.0F) {
                    this.hurtTime = this.maxHurtTime = 10;
                }
            }
        }

        return false;
    }

public void setCarcass(boolean carcass) {
        if(!this.world.isRemote && carcass != this.isCarcass && !this.wasMoved) {
            this.moveTicks = 18;
        }
        this.isCarcass = carcass;

        boolean carcassAllowed = RebornConfig.ENTITIES.allowCarcass;
        if (!this.world.isRemote) {
            this.dataManager.set(WATCHER_IS_CARCASS, this.isCarcass);
        }
        if (carcass && carcassAllowed) {
            this.setAnimation(EntityAnimation.DYING.get());
            this.carcassHealth = MathHelper.clamp(Math.max(1, (int) Math.sqrt(this.width * this.height)), 0, 8);
            this.ticksExisted = 0;
            this.inventory.dropItems(this.world, this.rand);
        }else if (carcass){
            this.setAnimation(EntityAnimation.DYING.get());
            this.carcassHealth = 0;
            this.inventory.dropItems(this.world, this.rand);
        }
    }

private void dropMeat(Entity attacker) {
        int fortune = 0;
        if (attacker instanceof EntityLivingBase) {
            fortune = EnchantmentHelper.getLootingModifier((EntityLivingBase) attacker);
        }

        int count = this.rand.nextInt(2) + 1 + fortune;

        boolean burning = this.isBurning();

        for (int i = 0; i < count; ++i) {
            int meta = EntityHandler.getDinosaurId(this.dinosaur);

            if (burning) {
                this.entityDropItem(new ItemStack(ItemHandler.DINOSAUR_STEAK, 1, meta), 0.0F);
            } else {
                this.dropStackWithGenetics(new ItemStack(ItemHandler.DINOSAUR_MEAT, 1, meta));
            }
        }
    }

public void respondToAttack(EntityLivingBase attacker) {
        if (attacker != null && !attacker.isDead && !(attacker instanceof EntityPlayer && ((EntityPlayer) attacker).capabilities.isCreativeMode)) {
            List<EntityLivingBase> enemies = new LinkedList<>();

            if (attacker instanceof DinosaurEntity) {
                DinosaurEntity enemyDinosaur = (DinosaurEntity) attacker;

                if (enemyDinosaur.herd != null) {
                    enemies.addAll(enemyDinosaur.herd.members);
                }
            } else {
                enemies.add(attacker);
            }

            if (enemies.size() > 0) {
                Herd herd = this.herd;

                if (herd != null) {
                    herd.fleeing = !herd.shouldDefend(enemies) || this.dinosaur.shouldFlee();

                    for (EntityLivingBase entity : enemies) {
                        if (!herd.enemies.contains(entity)) {
                            herd.enemies.add(entity);
                        }
                    }
                } else {
                    this.setAttackTarget(enemies.get(this.getRNG().nextInt(enemies.size())));
                }
            }
        }
    }
